"use client";
import { useEffect, useMemo, useState, type ReactNode } from "react";
import { Button, EmptyState, Input } from "./index";
import { Checkbox } from "./forms";
import { Pagination } from "./navigation";
export interface DataColumn<T> {
  id: string;
  header: string;
  accessor: (row: T) => string | number;
  cell?: (row: T) => ReactNode;
  sortable?: boolean;
}
export interface DataTableProps<T> {
  data: T[];
  columns: DataColumn<T>[];
  getRowId: (row: T) => string;
  caption: string;
  pageSize?: number;
  searchPlaceholder?: string;
  selectable?: boolean;
  onSelectionChange?: (ids: string[]) => void;
  emptyTitle?: string;
}
export function DataTable<T>({
  data,
  columns,
  getRowId,
  caption,
  pageSize = 5,
  searchPlaceholder = "搜索所有列…",
  selectable = false,
  onSelectionChange,
  emptyTitle = "没有匹配记录",
}: DataTableProps<T>) {
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [sort, setSort] = useState<{ id: string; direction: "asc" | "desc" }>();
  const [selected, setSelected] = useState<string[]>([]);
  const size = Math.max(1, Math.floor(pageSize));
  const rows = useMemo(() => {
    const filtered = data.filter((row) =>
      columns.some((column) =>
        String(column.accessor(row))
          .toLocaleLowerCase()
          .includes(query.toLocaleLowerCase()),
      ),
    );
    if (!sort) return filtered;
    const column = columns.find((c) => c.id === sort.id);
    return column
      ? [...filtered].sort((a, b) => {
          const av = column.accessor(a),
            bv = column.accessor(b);
          const order =
            typeof av === "number" && typeof bv === "number"
              ? av - bv
              : String(av).localeCompare(String(bv), undefined, {
                  numeric: true,
                });
          return sort.direction === "asc" ? order : -order;
        })
      : filtered;
  }, [data, columns, query, sort]);
  const pageCount = Math.max(1, Math.ceil(rows.length / size));
  const currentPage = Math.min(page, pageCount);
  const visible = rows.slice((currentPage - 1) * size, currentPage * size);
  const ids = visible.map(getRowId);
  const checked = ids.length > 0 && ids.every((id) => selected.includes(id));
  const mixed = ids.some((id) => selected.includes(id));
  const select = (next: string[]) => {
    setSelected(next);
    onSelectionChange?.(next);
  };
  useEffect(() => {
    const available = new Set(data.map(getRowId));
    const next = selected.filter((id) => available.has(id));
    if (next.length !== selected.length) {
      setSelected(next);
      onSelectionChange?.(next);
    }
  }, [data, getRowId, selected, onSelectionChange]);
  return (
    <div className="cs-data-table">
      <div className="cs-table-toolbar">
        <Input
          label="搜索记录"
          placeholder={searchPlaceholder}
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setPage(1);
          }}
        />
        <span className="cs-help" role="status">
          {rows.length} 条记录{selectable && ` · 已选 ${selected.length} 条`}
        </span>
      </div>
      {rows.length ? (
        <div className="cs-table-scroll">
          <table className="cs-table">
            <caption className="cs-sr-only">{caption}</caption>
            <thead>
              <tr>
                {selectable && (
                  <th scope="col">
                    <Checkbox
                      label={<span className="cs-sr-only">选择当前页</span>}
                      checked={checked ? true : mixed ? "indeterminate" : false}
                      onCheckedChange={(value) =>
                        select(
                          value === true
                            ? Array.from(new Set([...selected, ...ids]))
                            : selected.filter((id) => !ids.includes(id)),
                        )
                      }
                    />
                  </th>
                )}
                {columns.map((column) => (
                  <th
                    key={column.id}
                    scope="col"
                    aria-sort={
                      sort?.id === column.id
                        ? sort.direction === "asc"
                          ? "ascending"
                          : "descending"
                        : column.sortable
                          ? "none"
                          : undefined
                    }
                  >
                    {column.sortable ? (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() =>
                          setSort({
                            id: column.id,
                            direction:
                              sort?.id === column.id && sort.direction === "asc"
                                ? "desc"
                                : "asc",
                          })
                        }
                      >
                        {column.header}
                        <svg className="cs-sort-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                          {sort?.id !== column.id ? <><path d="M8 19V5m-4 4 4-4 4 4" /><path d="M16 5v14m-4-4 4 4 4-4" /></> : sort.direction === "asc" ? <path d="M12 19V5m-6 6 6-6 6 6" /> : <path d="M12 5v14m-6-6 6 6 6-6" />}
                        </svg>
                      </Button>
                    ) : (
                      column.header
                    )}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {visible.map((row) => (
                <tr
                  key={getRowId(row)}
                  data-selected={selected.includes(getRowId(row)) || undefined}
                >
                  {selectable && (
                    <td>
                      <Checkbox
                        label={
                          <span className="cs-sr-only">
                            选择记录 {getRowId(row)}
                          </span>
                        }
                        checked={selected.includes(getRowId(row))}
                        onCheckedChange={(value) =>
                          select(
                            value === true
                              ? [...selected, getRowId(row)]
                              : selected.filter((id) => id !== getRowId(row)),
                          )
                        }
                      />
                    </td>
                  )}
                  {columns.map((column) => (
                    <td key={column.id}>
                      {column.cell?.(row) ?? column.accessor(row)}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <EmptyState
          title={emptyTitle}
          description="请调整搜索词或检查数据来源。"
        />
      )}
      <div className="cs-table-footer">
        <span className="cs-help">
          第 {currentPage} / {pageCount} 页
        </span>
        <Pagination
          page={currentPage}
          pageCount={pageCount}
          onPageChange={setPage}
        />
      </div>
    </div>
  );
}

"use client";
import {
  useState,
  type HTMLAttributes,
  type ReactNode,
  type CSSProperties,
} from "react";
import * as P from "@radix-ui/react-progress";
import { cx } from "./utils";
export type Tone = "neutral" | "brand" | "success" | "warning" | "danger";
export function Badge({
  tone = "neutral",
  variant = "soft",
  children,
  ...props
}: HTMLAttributes<HTMLSpanElement> & {
  tone?: Tone;
  variant?: "soft" | "outline";
}) {
  return (
    <span
      {...props}
      className={cx(
        "cs-tag",
        `cs-tone-${tone}`,
        `cs-tag--${variant}`,
        props.className,
      )}
    >
      {children}
    </span>
  );
}
export function Avatar({
  name,
  src,
  size = "md",
}: {
  name: string;
  src?: string;
  size?: "sm" | "md" | "lg";
}) {
  const [failedSrc, setFailedSrc] = useState<string>();
  return (
    <span
      role="img"
      aria-label={name}
      className={cx("cs-avatar", `cs-avatar--${size}`)}
    >
      {src && src !== failedSrc ? (
        <img src={src} alt="" onError={() => setFailedSrc(src)} />
      ) : (
        <span aria-hidden="true">
          {name
            .trim()
            .split(/\s+/)
            .map((n) => Array.from(n)[0])
            .slice(0, 2)
            .join("") || "?"}
        </span>
      )}
    </span>
  );
}
export function Alert({
  title,
  children,
  tone = "neutral",
  action,
  ...props
}: Omit<HTMLAttributes<HTMLDivElement>, "title"> & {
  title: string;
  tone?: Tone;
  action?: ReactNode;
}) {
  return (
    <div
      role={tone === "danger" ? "alert" : "status"}
      {...props}
      className={cx("cs-alert", `cs-tone-${tone}`, props.className)}
    >
      <div className="cs-alert-content">
        <strong>{title}</strong>
        {children && <div>{children}</div>}
      </div>
      {action}
    </div>
  );
}
export function Progress({
  value,
  label,
  showValue = true,
}: {
  value: number | null;
  label: string;
  showValue?: boolean;
}) {
  const safe = value === null ? null : Math.max(0, Math.min(100, value));
  return (
    <div className="cs-field">
      <div className="cs-between">
        <span className="cs-label">{label}</span>
        {showValue && (
          <span className="cs-help">
            {safe === null ? "处理中…" : `${Math.round(safe)}%`}
          </span>
        )}
      </div>
      <P.Root value={safe} max={100} aria-label={label} className="cs-progress">
        <P.Indicator
          className="cs-progress-indicator"
          style={
            safe === null
              ? undefined
              : { transform: `translateX(-${100 - safe}%)` }
          }
        />
      </P.Root>
    </div>
  );
}
export function Skeleton({
  width = "100%",
  height = 16,
  className,
  ...props
}: HTMLAttributes<HTMLDivElement> & {
  width?: CSSProperties["width"];
  height?: CSSProperties["height"];
}) {
  return (
    <div
      {...props}
      aria-hidden="true"
      className={cx("cs-skeleton", className)}
      style={{ width, height, ...props.style }}
    />
  );
}
export function Separator({
  orientation = "horizontal",
  decorative = true,
}: {
  orientation?: "horizontal" | "vertical";
  decorative?: boolean;
}) {
  return (
    <div
      role={decorative ? "none" : "separator"}
      aria-orientation={decorative ? undefined : orientation}
      className={cx("cs-separator", `cs-separator--${orientation}`)}
    />
  );
}

.cs-button.cs-button--sm {
  min-height: 28px;
  padding: 0 10px;
  font-size: 12px;
}
.cs-button.cs-button--lg {
  min-height: 48px;
  padding: 0 20px;
  font-size: 16px;
}
.cs-button {
  transition:
    background var(--cs-duration-fast),
    border-color var(--cs-duration-fast),
    color var(--cs-duration-fast);
}
.cs-button:active:not(:disabled) {
  transform: translateY(1px);
}
.cs-label {
  font-size: var(--cs-font-size);
  font-weight: 600;
}
.cs-between {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.cs-textarea {
  resize: vertical;
  line-height: 1.6;
  min-height: 100px;
}
.cs-select {
  appearance: auto;
}
.cs-choice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: var(--cs-font-size);
}
.cs-choice label {
  cursor: pointer;
  line-height: 22px;
}
.cs-choice p {
  margin: 3px 0 0;
}
.cs-checkbox,
.cs-radio {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  margin: 2px 0 0;
  padding: 0;
  width: 18px;
  height: 18px;
  border: 1px solid var(--cs-border);
  border-radius: var(--cs-radius-sm);
  background: var(--cs-surface);
  color: var(--cs-on-brand);
  cursor: pointer;
}
.cs-checkbox[data-state="checked"],
.cs-checkbox[data-state="indeterminate"] {
  background: var(--cs-brand);
  border-color: var(--cs-brand);
}
.cs-checkbox[data-disabled],
.cs-radio[data-disabled],
.cs-switch[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
.cs-checkbox span {
  font-size: 13px;
  line-height: 1;
}
.cs-radio {
  border-radius: 50%;
  color: var(--cs-brand);
}
.cs-radio[data-state="checked"] {
  border-color: var(--cs-brand);
}
.cs-radio-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
}
.cs-radio-group {
  display: grid;
  gap: 14px;
}
.cs-switch {
  border: none;
  background: var(--cs-border);
  border-radius: 99px;
  width: 36px;
  height: 22px;
  padding: 3px;
  flex-shrink: 0;
  cursor: pointer;
}
.cs-switch[data-state="checked"] {
  background: var(--cs-switch-on);
}
.cs-switch-thumb {
  display: block;
  width: 16px;
  height: 16px;
  background: var(--cs-surface);
  border-radius: 50%;
  transition: transform var(--cs-duration-fast);
}
.cs-switch-thumb[data-state="checked"] {
  transform: translateX(14px);
}
.cs-slider {
  position: relative;
  display: flex;
  align-items: center;
  touch-action: none;
  user-select: none;
  height: 24px;
  width: 100%;
}
.cs-slider-track {
  position: relative;
  flex-grow: 1;
  height: 5px;
  border-radius: 99px;
  background: var(--cs-border);
}
.cs-slider-range {
  position: absolute;
  height: 100%;
  border-radius: 99px;
  background: var(--cs-brand);
}
.cs-slider-thumb {
  display: block;
  width: 18px;
  height: 18px;
  border: 2px solid var(--cs-brand);
  border-radius: 50%;
  background: var(--cs-surface);
  box-shadow: var(--cs-shadow-sm);
}
.cs-slider[data-disabled] {
  opacity: 0.45;
}
.cs-combobox-trigger {
  width: 100%;
  justify-content: space-between;
  font-weight: 400;
}
.cs-combobox {
  width: var(--radix-popover-trigger-width);
  padding: 4px !important;
  min-width: 220px;
}
.cs-command-input {
  width: 100%;
  border: 0;
  border-bottom: 1px solid var(--cs-border);
  padding: 12px;
  font: inherit;
  color: var(--cs-text);
  background: transparent;
}
.cs-command-list {
  max-height: 240px;
  overflow: auto;
  padding: 4px;
}
.cs-command-item {
  padding: 8px 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-radius: var(--cs-radius);
  cursor: pointer;
  font-size: 14px;
}
.cs-command-item[data-selected="true"] {
  background: var(--cs-subtle);
  color: var(--cs-brand);
}
.cs-command-item[data-disabled="true"] {
  opacity: 0.4;
  cursor: not-allowed;
}
.cs-command-empty {
  padding: 20px;
  text-align: center;
  font-size: 13px;
  color: var(--cs-muted);
}
.cs-file-upload {
  border: 1px dashed var(--cs-border);
  border-radius: var(--cs-radius);
  padding: 24px;
  display: grid;
  gap: 12px;
  background: var(--cs-subtle);
}
.cs-file-upload input {
  font: inherit;
  color: var(--cs-text);
  max-width: 100%;
}
.cs-file-upload input::file-selector-button {
  padding: 8px 12px;
  margin-right: 12px;
  border: 1px solid var(--cs-border);
  border-radius: var(--cs-radius);
  background: var(--cs-surface);
  color: var(--cs-text);
  cursor: pointer;
}
.cs-file-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.cs-file-list li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--cs-border);
  font-size: 13px;
  overflow-wrap: anywhere;
}
.cs-file-list span {
  white-space: nowrap;
  color: var(--cs-muted);
}
.cs-tabs-list {
  display: flex;
  gap: 4px;
  align-items: center;
  overflow-x: auto;
}
.cs-tabs-list--line {
  border-bottom: 1px solid var(--cs-border);
}
.cs-tabs-trigger {
  white-space: nowrap;
  border: 0;
  border-bottom: 2px solid transparent;
  padding: 10px 16px;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  background: transparent;
  color: var(--cs-muted);
  cursor: pointer;
}
.cs-tabs-trigger[data-state="active"] {
  border-color: var(--cs-brand);
  color: var(--cs-brand);
}
.cs-tabs-trigger:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.cs-tabs-list--pill {
  background: var(--cs-subtle);
  padding: 4px;
  border-radius: var(--cs-radius-lg);
  width: fit-content;
}
.cs-tabs-list--pill .cs-tabs-trigger {
  border: 0;
  border-radius: var(--cs-radius);
  padding: 7px 14px;
}
.cs-tabs-list--pill .cs-tabs-trigger[data-state="active"] {
  background: var(--cs-surface);
  box-shadow: var(--cs-shadow-sm);
}
.cs-tabs-content {
  padding-top: 20px;
  outline: none;
}
.cs-accordion-item {
  border-bottom: 1px solid var(--cs-border);
}
.cs-accordion-header {
  margin: 0;
}
.cs-accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: none;
  padding: 16px 0;
  background: transparent;
  color: var(--cs-text);
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}
.cs-accordion-trigger span {
  font-size: 20px;
  color: var(--cs-muted);
  transition: transform var(--cs-duration-fast);
}
.cs-accordion-trigger[data-state="open"] span {
  transform: rotate(45deg);
}
.cs-accordion-trigger:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.cs-accordion-content > div {
  padding: 0 0 16px;
  color: var(--cs-muted);
  font-size: 14px;
  line-height: 1.7;
}
.cs-breadcrumbs ol {
  align-items: center;
  line-height: 20px;
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  gap: 10px;
  margin: 0;
  padding: 0;
  font-size: 13px;
}
.cs-breadcrumbs li {
  display: flex;
  align-items: center;
  gap: 8px;
}
.cs-breadcrumbs a {
  color: var(--cs-muted);
  text-decoration: none;
}
.cs-breadcrumbs a:hover {
  color: var(--cs-brand);
  text-decoration: underline;
}
.cs-pagination {
  display: flex;
  gap: 4px;
  align-items: center;
}
.cs-pagination > span {
  display: flex;
  align-items: center;
}
.cs-pagination .cs-button {
  width: 32px;
  height: 32px;
  min-height: 32px;
  min-width: 32px;
  padding: 0;
  flex-shrink: 0;
  box-sizing: border-box;
  font-size: 12px;
}
.cs-page-gap {
  color: var(--cs-muted);
  padding: 0 6px;
}
.cs-popover,
.cs-dropdown {
  z-index: var(--cs-z-popover);
  font-family: var(--cs-font);
  background: var(--cs-surface);
  color: var(--cs-text);
  border: 1px solid var(--cs-border);
  border-radius: var(--cs-radius-lg);
  padding: 16px;
  box-shadow: var(--cs-shadow);
  max-width: calc(100vw - 32px);
}
.cs-popover {
  width: 300px;
}
.cs-dropdown {
  padding: 5px;
  min-width: 200px;
}
.cs-menu-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 9px 12px;
  border-radius: var(--cs-radius);
  outline: none;
  cursor: pointer;
  font-size: 13px;
}
.cs-menu-item[data-highlighted] {
  background: var(--cs-subtle);
}
.cs-menu-item[data-disabled] {
  opacity: 0.4;
  cursor: not-allowed;
}
.cs-menu-shortcut {
  font-size: 11px;
  color: var(--cs-muted);
}
.cs-tooltip {
  z-index: var(--cs-z-tooltip);
  font-family: var(--cs-font);
  font-size: 12px;
  line-height: 1.5;
  padding: 7px 10px;
  max-width: 260px;
  border-radius: var(--cs-radius);
  background: var(--cs-text);
  color: var(--cs-surface);
  box-shadow: var(--cs-shadow-sm);
}
.cs-tooltip-arrow {
  fill: var(--cs-text);
}
.cs-sheet {
  position: fixed;
  top: 0;
  bottom: 0;
  width: min(460px, calc(100vw - 32px));
  padding: 24px;
  background: var(--cs-surface);
  color: var(--cs-text);
  border: 1px solid var(--cs-border);
  z-index: var(--cs-z-modal);
  font-family: var(--cs-font);
  box-shadow: var(--cs-shadow);
  overflow: auto;
}
.cs-sheet--right {
  right: 0;
}
.cs-sheet--left {
  left: 0;
}
.cs-sheet h2 {
  font-size: 20px;
  margin: 0;
}
.cs-sheet-body {
  margin-top: 24px;
}
.cs-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  flex-wrap: wrap;
  margin-top: 20px;
}
.cs-actions .cs-button {
  margin-top: 0;
}
.cs-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.5;
  border-radius: var(--cs-radius);
  border: 1px solid transparent;
  background: var(--tone-bg);
  color: var(--tone-fg);
}
.cs-tone-neutral {
  --tone-bg: var(--cs-subtle);
  --tone-fg: var(--cs-muted);
}
.cs-tone-brand {
  --tone-bg: var(--cs-brand-subtle);
  --tone-fg: var(--cs-brand);
}
.cs-tone-success {
  --tone-bg: var(--cs-success-bg);
  --tone-fg: var(--cs-success-fg);
}
.cs-tone-warning {
  --tone-bg: var(--cs-warning-bg);
  --tone-fg: var(--cs-warning-fg);
}
.cs-tone-danger {
  --tone-bg: var(--cs-danger-bg);
  --tone-fg: var(--cs-danger-fg);
}
.cs-tag--outline {
  background: transparent;
  border-color: currentColor;
}
.cs-avatar {
  width: 40px;
  height: 40px;
  display: inline-grid;
  place-items: center;
  background: var(--cs-brand-subtle);
  color: var(--cs-brand);
  font-size: 14px;
  font-weight: 600;
  border: 1px solid var(--cs-border);
