export interface ComboboxProps {
  label: string;
  options: ChoiceOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  emptyText?: string;
}
export function Combobox({
  label,
  options,
  value,
  defaultValue = "",
  onValueChange,
  placeholder = "选择项目",
  disabled,
  emptyText = "没有匹配项",
}: ComboboxProps) {
  const [open, setOpen] = useState(false);
  const [internal, setInternal] = useState(defaultValue);
  const selected = value ?? internal;
  const id = useId();
  return (
    <div className="cs-field">
      <span id={id} className="cs-label">
        {label}
      </span>
      <P.Root open={open} onOpenChange={setOpen}>
        <P.Trigger asChild>
          <Button
            variant="secondary"
            className="cs-combobox-trigger"
            disabled={disabled}
            aria-labelledby={id}
            aria-label={`${label}：${options.find((o) => o.value === selected)?.label ?? placeholder}`}
          >
            {options.find((o) => o.value === selected)?.label ?? placeholder}
            <svg className="cs-combobox-chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6" /></svg>
          </Button>
        </P.Trigger>
        <P.Portal>
          <P.Content
            className="cs-popover cs-combobox"
            sideOffset={6}
            align="start"
          >
            <Command label={`${label}搜索`}>
              <Command.Input
                placeholder="搜索…"
                aria-label={`搜索${label}`}
                className="cs-command-input"
              />
              <Command.List className="cs-command-list">
                <Command.Empty className="cs-command-empty">
                  {emptyText}
                </Command.Empty>
                {options.map((option) => (
                  <Command.Item
                    key={option.value}
                    value={option.value}
                    keywords={[option.label]}
                    disabled={option.disabled}
                    onSelect={() => {
                      setInternal(option.value);
                      onValueChange?.(option.value);
                      setOpen(false);
                    }}
                    className="cs-command-item"
                  >
                    {option.label}
                    <span aria-hidden="true">
                      {option.value === selected ? "✓" : ""}
                    </span>
                  </Command.Item>
                ))}
              </Command.List>
            </Command>
          </P.Content>
        </P.Portal>
      </P.Root>
    </div>
  );
}
export function FileUpload({
  label,
  accept,
  multiple = false,
  maxSize = 10 * 1024 * 1024,
  disabled,
  onFilesChange,
}: {
  label: string;
  accept?: string;
  multiple?: boolean;
  maxSize?: number;
  disabled?: boolean;
  onFilesChange?: (files: File[]) => void;
}) {
  const id = useId();
  const [files, setFiles] = useState<File[]>([]);
  const [error, setError] = useState("");
  return (
    <div className="cs-field">
      <label htmlFor={id}>{label}</label>
      <div className="cs-file-upload">
        <input
          id={id}
          type="file"
          accept={accept}
          multiple={multiple}
          disabled={disabled}
          aria-describedby={`${id}-help`}
          aria-invalid={!!error}
          onChange={(e) => {
            const next = Array.from(e.target.files ?? []);
            if (next.some((f) => f.size > maxSize)) {
              setError(`文件不能超过 ${Math.round(maxSize / 1024 / 1024)} MB`);
              e.target.value = "";
              return;
            }
            setError("");
            setFiles(next);
            onFilesChange?.(next);
          }}
        />
        <span className="cs-help" id={`${id}-help`}>
          {error ||
            `仅本地选择，最大 ${Math.round(maxSize / 1024 / 1024)} MB；上传由业务层处理。`}
        </span>
      </div>
      {files.length > 0 && (
        <ul className="cs-file-list">
          {files.map((file, i) => (
            <li key={`${file.name}-${i}`}>
              {file.name}
              <span>{Math.ceil(file.size / 1024)} KB</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

