export function AlertDialog({
  trigger,
  title,
  description,
  onConfirm,
  confirmLabel = "确认",
  cancelLabel = "取消",
}: {
  trigger: ReactNode;
  title: string;
  description: string;
  onConfirm: () => void | Promise<void>;
  confirmLabel?: string;
  cancelLabel?: string;
}) {
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState("");
  return (
    <AD.Root
      open={open}
      onOpenChange={(next) => {
        if (!pending) {
          setOpen(next);
          if (next) setError("");
        }
      }}
    >
      <AD.Trigger asChild>{trigger}</AD.Trigger>
      <AD.Portal>
        <AD.Overlay className="cs-dialog-overlay" />
        <AD.Content className="cs-dialog">
          <AD.Title>{title}</AD.Title>
          <AD.Description>{description}</AD.Description>
          {error && (
            <p role="alert" className="cs-error">
              {error}
            </p>
          )}
          <div className="cs-actions">
            <AD.Cancel asChild>
              <Button disabled={pending} variant="secondary">
                {cancelLabel}
              </Button>
            </AD.Cancel>
            <AD.Action asChild>
              <Button
                variant="danger"
                loading={pending}
                onClick={async (e) => {
                  e.preventDefault();
                  setPending(true);
                  setError("");
                  try {
                    await onConfirm();
                    setOpen(false);
                  } catch (err) {
                    setError(
                      err instanceof Error ? err.message : "操作失败，请重试。",
                    );
                  } finally {
                    setPending(false);
                  }
                }}
              >
                {confirmLabel}
              </Button>
            </AD.Action>
          </div>
        </AD.Content>
      </AD.Portal>
    </AD.Root>
  );
}
