/* Fields keep their control height when adjacent content is taller. */
.cs-field { align-content: start; min-width: 0; }
.cs-input:not(.cs-textarea) {
  height: var(--cs-control-height);
  padding-top: 0;
  padding-bottom: 0;
}
.cs-button.cs-combobox-trigger {
  height: var(--cs-control-height);
  box-sizing: border-box;
  padding: 0 12px;
  gap: 12px;
  text-align: left;
  color: var(--cs-text);
  background: var(--cs-surface);
}
.cs-combobox-chevron { flex: 0 0 16px; color: var(--cs-muted); }
.cs-button.cs-combobox-trigger:focus,
.cs-button.cs-combobox-trigger[data-state="open"] {
  border-color: var(--cs-brand);
  outline: none;
  box-shadow: none;
}
@media (forced-colors: active) {
  .cs-button.cs-combobox-trigger:focus-visible { outline: 2px solid Highlight; outline-offset: 2px; }
}

.cs-device-table {
  line-height: 20px;
  letter-spacing: normal;
}
.cs-device-table :is(th, td) {
  padding: 12px 16px;
  vertical-align: middle;
}
.cs-device-table thead th { padding-top: 12px; padding-bottom: 12px; }
.cs-device-table small {
  margin-top: 2px;
  line-height: 16px;
  font-weight: 400;
}
.cs-device-table .cs-button { min-height: 32px; padding: 0 12px; }
[data-density="compact"] .cs-device-table :is(th, td) { padding-top: 6px; padding-bottom: 6px; }

/* The enclosing frame supplies the top edge; avoid a second collapsed border. */
.cs-table thead tr:first-child > :is(th, td) { border-top: 0; }

.cs-device-table .cs-button { font-weight: var(--cs-weight-normal); }

"use client";
import {
  createContext,
  useContext,
  useRef,
  useState,
  type ReactNode,
} from "react";
import * as T from "@radix-ui/react-toast";
import { Button } from "./index";
export interface ToastMessage {
  title: string;
  description?: string;
  duration?: number;
  action?: { label: string; altText: string; onClick: () => void };
}
const ToastContext = createContext<((message: ToastMessage) => void) | null>(
  null,
);
export function ToastProvider({ children }: { children: ReactNode }) {
  const nextId = useRef(0);
  const [messages, setMessages] = useState<(ToastMessage & { id: number })[]>(
    [],
  );
  return (
    <ToastContext.Provider
      value={(message) => {
        const id = nextId.current++;
        setMessages((current) => [...current.slice(-4), { ...message, id }]);
      }}
    >
      <T.Provider swipeDirection="right">
        {children}
        {messages.map((message) => (
          <T.Root
            key={message.id}
            className="cs-toast"
            duration={message.duration ?? 5000}
            onOpenChange={(open) => {
              if (!open)
                setMessages((current) =>
                  current.filter((m) => m.id !== message.id),
                );
            }}
          >
            <div>
              <T.Title className="cs-label">{message.title}</T.Title>
              {message.description && (
                <T.Description className="cs-help">
                  {message.description}
                </T.Description>
              )}
            </div>
            {message.action && (
              <T.Action altText={message.action.altText} asChild>
                <Button
                  variant="secondary"
                  size="sm"
                  onClick={message.action.onClick}
                >
                  {message.action.label}
                </Button>
              </T.Action>
            )}
            <T.Close asChild>
              <Button variant="ghost" size="sm" aria-label="关闭通知">
                ×
              </Button>
            </T.Close>
          </T.Root>
        ))}
        <T.Viewport className="cs-toast-viewport" label="通知（F8）" />
      </T.Provider>
    </ToastContext.Provider>
  );
}
export function useToast() {
  const toast = useContext(ToastContext);
  if (!toast) throw new Error("useToast 必须位于 ToastProvider 中");
  return toast;
}

"use client";
import { useRef, useState, useEffect, type VideoHTMLAttributes } from 'react';
export interface VideoPlayerProps extends Omit<VideoHTMLAttributes<HTMLVideoElement>, 'controls' | 'title'> {
  title: string;
  captions?: { src: string; srcLang: string; label: string; default?: boolean }[];
}
export function VideoPlayer({ title, src, poster, captions = [], className, onError, onLoadedData, onWaiting, onPlaying, ...props }: VideoPlayerProps) {
  const video = useRef<HTMLVideoElement>(null);
  const [state, setState] = useState<'ready'|'loading'|'error'>('ready');
  const [speed, setSpeed] = useState('1');
  useEffect(()=>{setState('ready');setSpeed('1');},[src]);
  return <figure className={`cs-video-player ${className ?? ''}`}>
    <div className="cs-video-stage">
      {src ? <video {...props} ref={video} src={src} poster={poster} controls playsInline preload="metadata" aria-label={title}
        onError={event=>{setState('error');onError?.(event);}}
        onLoadedData={event=>{setState('ready');onLoadedData?.(event);}}
        onWaiting={event=>{setState('loading');onWaiting?.(event);}}
        onPlaying={event=>{setState('ready');onPlaying?.(event);}}>
        {captions.map(track=><track key={track.src} kind="captions" {...track} />)}
        当前浏览器不支持视频播放。
      </video> : <div className="cs-video-message"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="m10 8 6 4-6 4Z"/></svg><strong>尚未选择视频</strong><span>提供视频地址或在示例中选择本地文件。</span></div>}
      {src && state==='loading' && <div className="cs-video-status" role="status">正在缓冲…</div>}
      {src && state==='error' && <div className="cs-video-message cs-video-error" role="alert"><strong>视频无法播放</strong><span>请检查地址、文件格式或网络连接。</span><button type="button" className="cs-button cs-button--secondary" onClick={()=>{setState('loading');video.current?.load();}}>重试</button></div>}
    </div>
    <figcaption className="cs-video-caption"><span>{title}</span><label>播放速度<select aria-label="播放速度" value={speed} disabled={!src || state==='error'} onChange={e=>{setSpeed(e.target.value);if(video.current)video.current.playbackRate=Number(e.target.value);}}>{['0.5','0.75','1','1.25','1.5','2'].map(rate=><option key={rate} value={rate}>{rate}×</option>)}</select></label></figcaption>
  </figure>;
}

